theorem analyticOnNhd_finiteBlaschke {f : ℂ → ℂ} {R : ℝ}
    (hf : AnalyticOnNhd ℂ f (closedBall 0 R)) :
    AnalyticOnNhd ℂ (finiteBlaschke f R) (closedBall 0 R)

theorem canonical_numerator_ne_zero {R : ℝ} {w z : ℂ}
    (hw : w ∈ ball 0 R) (hz : z ∈ closedBall 0 R) :
    (R : ℂ) ^ 2 - conj w * z ≠ 0

theorem divisor_sphere_eq_zero {f : ℂ → ℂ} {R : ℝ}
    (hf : AnalyticOnNhd ℂ f (closedBall 0 R))
    (hnz : ∀ z ∈ sphere 0 R, f z ≠ 0) : divisor f (sphere 0 R) = 0

theorem norm_finiteBlaschke_on_sphere {f : ℂ → ℂ} {R : ℝ}
    (hf : AnalyticOnNhd ℂ f (closedBall 0 R)) {z : ℂ} (hz : z ∈ sphere 0 R) :
    ‖finiteBlaschke f R z‖ = 1

lemma mem_zeroSupport {f : ℂ → ℂ} {S : ℝ}
    (hf : AnalyticOnNhd ℂ f (closedBall 0 S)) {a : ℂ} :
    a ∈ zeroSupport hf ↔ divisor f (ball 0 S) a ≠ 0

lemma multiplicity_nonneg {f : ℂ → ℂ} {S : ℝ}
    (hf : AnalyticOnNhd ℂ f (closedBall 0 S)) (a : ℂ) :
    0 ≤ multiplicity f S a

theorem radialPotential_intervalIntegrable {f : ℂ → ℂ} {S R δ a b : ℝ}
    (hf : AnalyticOnNhd ℂ f (closedBall 0 S)) (hR : 0 < R) (hδ : 0 < δ) :
    IntervalIntegrable (radialPotential hf R δ) volume a b

theorem radialPotential_nonneg {f : ℂ → ℂ} {S R δ r : ℝ}
    (hf : AnalyticOnNhd ℂ f (closedBall 0 S)) (hR : 0 ≤ R) (hδ : 0 ≤ δ) :
    0 ≤ radialPotential hf R δ r

theorem weighted_divisor_finsum {f : ℂ → ℂ} {S : ℝ}
    (hf : AnalyticOnNhd ℂ f (closedBall 0 S)) (H : ℂ → ℝ) :
    (∑ᶠ a, multiplicity f S a * H a) = ∑ a ∈ zeroSupport hf, multiplicity f S a * H a

theorem zeroCount_eq_divisor_sum {f : ℂ → ℂ} {S : ℝ}
    (hf : AnalyticOnNhd ℂ f (closedBall 0 S)) :
    zeroCount hf = (∑ᶠ a, divisor f (ball 0 S) a : ℤ)

theorem uniformContinuous_of_asymptotic [l.NeBot] {f : M → Y}
    (hG : AsymptoticUniformEquicontinuous G l)
    (hlim : ∀ x, Tendsto (fun i => G i x) l (𝓝 (f x))) : UniformContinuous f

theorem uniform_of_asymptotic_pointwise [CompactSpace M] [l.NeBot] {f : M → Y}
    (hG : AsymptoticUniformEquicontinuous G l)
    (hlim : ∀ x, Tendsto (fun i => G i x) l (𝓝 (f x))) : TendstoUniformly G f l

theorem ZeroRadialDensity.union {E F : Set ℝ}
    (hE : ZeroRadialDensity E) (hF : ZeroRadialDensity F) :
    ZeroRadialDensity (E ∪ F)

theorem majorant_intervalIntegrable {f : ℂ → ℂ} {S G R ρ δ : ℝ}
    (hfS : AnalyticOnNhd ℂ f (closedBall 0 S)) (hR : 0 < R) (hδ : 0 < δ) :
    IntervalIntegrable (majorant hfS G R ρ δ) volume R (2 * R)

theorem majorant_nonneg {f : ℂ → ℂ} {S G R ρ δ r : ℝ}
    (hfS : AnalyticOnNhd ℂ f (closedBall 0 S)) (hG : 0 ≤ G) (hR : 0 < R) (hδ : 0 ≤ δ) :
    0 ≤ majorant hfS G R ρ δ r

theorem measurable_majorant {f : ℂ → ℂ} {S : ℝ}
    (hfS : AnalyticOnNhd ℂ f (closedBall 0 S)) (G R ρ δ : ℝ) :
    Measurable (majorant hfS G R ρ δ)

theorem measurable_radialPotential {f : ℂ → ℂ} {S : ℝ}
    (hfS : AnalyticOnNhd ℂ f (closedBall 0 S)) (R δ : ℝ) :
    Measurable (LevinFiniteProduct.radialPotential hfS R δ)

theorem zero_of_mem_zeroSupport {f : ℂ → ℂ} {S : ℝ}
    (hfS : AnalyticOnNhd ℂ f (closedBall 0 S)) {z : ℂ}
    (hz : z ∈ LevinFiniteProduct.zeroSupport hfS) : f z = 0

theorem asymptoticUniformEquicontinuous_mono {ι M Y : Type*}
    [PseudoMetricSpace M] [MetricSpace Y] {G : ι → M → Y} {l k : Filter ι}
    (hG : AsymptoticUniformEquicontinuous G l) (hkl : k ≤ l) :
    AsymptoticUniformEquicontinuous G k

theorem outsideFilter_le_of_eventually_contains {E F : Set ℝ}
    (h : ∃ A : ℝ, ∀ r, A ≤ r → r ∈ E → r ∈ F) :
    outsideFilter F ≤ outsideFilter E

theorem inverse_canonical_lower {S : ℝ} {a z : ℂ}
    (hS : 0 < S) (ha : a ∈ ball 0 S) (hz : z ∈ closedBall 0 S) :
    ‖z - a‖ / (2 * S) ≤ ‖(canonicalFactor S a z)⁻¹‖

theorem zeroIndex_card {f : ℂ → ℂ} {S : ℝ}
    (hf : AnalyticOnNhd ℂ f (closedBall 0 S)) :
    (Fintype.card (ZeroIndex hf) : ℝ) = LevinFiniteProduct.zeroCount hf

theorem radiusMass_eq_zero_below_scale (D : DiskFamily) {s R : ℝ}
    (hcenter : ∀ k, D.radius k ≠ 0 → s ≤ ‖D.center k‖) (hR : R < s) :
    radiusMass D R = 0

theorem density_bound_union_zero {E D : Set ℝ} {η : ℝ}
    (hE : EventuallyDensityLE E η) (hD : ZeroRadialDensity D) (hη : 0 < η) :
    EventuallyDensityLE (E ∪ D) (2 * η)

theorem exists_ge_outside_of_density_bound {E : Set ℝ} {η : ℝ}
    (hE : EventuallyDensityLE E η) (hη : η ≤ 1 / 2) (A : ℝ) :
    ∃ r : ℝ, A ≤ r ∧ r ∉ E

theorem outsideFilter_neBot_of_density_bound {E : Set ℝ} {η : ℝ}
    (hE : EventuallyDensityLE E η) (hη : η ≤ 1 / 2) :
    (outsideFilter E).NeBot

theorem dyadic_shell_index_unique {m n : ℕ} {r : ℝ}
    (hm : r ∈ Ico ((2 : ℝ) ^ m) (2 * 2 ^ m))
    (hn : r ∈ Ico ((2 : ℝ) ^ n) (2 * 2 ^ n)) : m = n

theorem exists_small_scale {cost : ℝ → ℝ}
    (hc : Tendsto cost (𝓝[>] (0 : ℝ)) (𝓝 0)) {t : ℝ} (ht : 0 < t) :
    ∃ δ : ℝ, 0 < δ ∧ δ ≤ 1 ∧ cost δ ≤ t

theorem finitePositiveType_remove_monomial {f F : ℂ → ℂ} {m : ℕ} {ρ : ℝ}
    (hρ : 0 < ρ) (htype : FinitePositiveType f ρ)
    (hfactor : ∀ z : ℂ, f z = z ^ m * F z) : FinitePositiveType F ρ

theorem rayRegular_remove_monomial {f F : ℂ → ℂ} {m : ℕ} {ρ a : ℝ} {ζ : Direction}
    (hρ : 0 < ρ) (hfactor : ∀ z : ℂ, f z = z ^ m * F z)
    (hreg : RayRegular f ρ ζ a) : RayRegular F ρ ζ a

theorem ray_nonzero_iff {f F : ℂ → ℂ} {m : ℕ}
    (hfactor : ∀ z : ℂ, f z = z ^ m * F z) {r : ℝ} (hr : 0 < r) (ζ : Direction) :
    f (rayPoint r ζ) ≠ 0 ↔ F (rayPoint r ζ) ≠ 0

theorem annularGrid_covers {n : ℕ} (hn : 0 < n) {z : ℂ}
    (hz : ‖z‖ ∈ Icc (1 : ℝ) 2) :
    ∃ c ∈ annularGrid n, ‖z - c‖ ≤ 2 / n

theorem radialRegular_le_limsup {f : ℂ → ℂ} {ρ : ℝ} {h : Direction → ℝ}
    (hf : RadialRegular f ρ h) (ζ : Direction) :
    (h ζ : EReal) ≤ Filter.limsup (fun r => extendedNormalizedLog f ρ r ζ) atTop

theorem rayRegular_le_limsup {f : ℂ → ℂ} {ρ : ℝ} {ζ : Direction} {a : ℝ}
    (hf : RayRegular f ρ ζ a) :
    (a : EReal) ≤ Filter.limsup (fun r => extendedNormalizedLog f ρ r ζ) atTop

theorem poissonKernel_nonneg {S : ℝ} {w z : ℂ}
    (hw : w ∈ ball 0 S) (hz : z ∈ sphere 0 S) :
    0 ≤ poissonKernel 0 w z

theorem diskRegular_of_radialRegular {f : ℂ → ℂ} {ρ : ℝ} {h : Direction → ℝ}
    (hf : Differentiable ℂ f) (hρ : 0 < ρ) (htype : FinitePositiveType f ρ)
    (hreg : RadialRegular f ρ h) : DiskRegular f ρ h
